#requires -Version 5.1
<#
    Strings.ps1
    UI string tables for Session Recovery. English is the master table and
    the fallback; every other language overrides the keys it translates.
    Usage:  $strings = Get-SRStrings -Language 'fr';  $strings.NavDashboard
#>

function Get-SRLanguageList {
    return @(
        [pscustomobject]@{ Key = 'en'; Label = 'English' }
        [pscustomobject]@{ Key = 'ar'; Label = 'العربية' }
        [pscustomobject]@{ Key = 'fr'; Label = 'Français' }
        [pscustomobject]@{ Key = 'es'; Label = 'Español' }
        [pscustomobject]@{ Key = 'de'; Label = 'Deutsch' }
        [pscustomobject]@{ Key = 'pt'; Label = 'Português' }
        [pscustomobject]@{ Key = 'ru'; Label = 'Русский' }
        [pscustomobject]@{ Key = 'zh'; Label = '中文' }
        [pscustomobject]@{ Key = 'tr'; Label = 'Türkçe' }
    )
}

function Test-SRRtlLanguage {
    param([string]$Language)
    return (@('ar', 'he', 'fa', 'ur') -contains ([string]$Language).ToLowerInvariant())
}

