    $overlay = $overlays[$lang]
    if ($null -eq $overlay) { return $english }
    $merged = @{}
    foreach ($key in $english.Keys) { $merged[$key] = $english[$key] }
    foreach ($key in $overlay.Keys) { $merged[$key] = $overlay[$key] }
    return $merged
}
